// === Tab: MovingCube ===
class MovingCube {
	constructor(rel, sze, bst = "0", seq = "ZyxzYX", sid = 0, frms = 30) {
		//
		this.rel = rel; // bottom plane is relative to this
		this.sze = sze; // size of the cube
		this.sze2 = sze/2;
		this.bst = bst; // block start, bottom sw0 nw1 ne2 se3, top sw4 nw5 ne6 se7
		// sequence
		this.seq = seq;
		this.sid = sid; // current index in sequence
		// current frame between indexes and number of frames to switch positition
		this.frm = 0;
		this.frms = 30;
		// current point, next point, curren pos (intermidiate pos)
		this.pt1 = createVector(-this.sze2, this.sze2, this.sze2);
		this.pt2 = this.pt1.copy();
		this.calcNextPos(true);
	}

	calcNextPos(switchPts = false) {
		if (switchPts) {
			this.pt1 = this.pt2.copy();
			this.sid = (this.sid + 1) % this.seq.length;
		}

		const dir = this.seq[this.sid];
		if (dir === "x") this.pt2.x += this.sze;
		if (dir === "X") this.pt2.x -= this.sze;
		if (dir === "y") this.pt2.y += this.sze;
		if (dir === "Y") this.pt2.y -= this.sze;
		if (dir === "z") this.pt2.z += this.sze;
		if (dir === "Z") this.pt2.Z -= this.sze;

		this.pos = this.pt1.copy();

		this.frm = 0;
	}

	update() {
		//
		this.frm = (this.frm + 1) % this.frms;
		if (this.frm === 0) this.calcNextPos(true);

		const f = pow(this.frm/this.frms, 2);
		this.pos = p5.Vector.lerp(this.pt1, this.pt2, f);
	}

	draw() {
		//
		push();
		if (this.rel) translate(this.rel);
		translate(this.pos);
		box(this.sze);
		pop();
	}
}

