let S;
const sequence = [""];
let mcubes;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	frameRate(30);
	S = max(width, height) * 0.5;
	stroke("pink"); // stroke("deeppink");
	noFill();

	mcubes = [];
	mcubes.push(new MovingCube(createVector(0, S/2, 0), S/2, 0, "ZYxzyX", 0));
}

function draw() {
	background("navy");
	debugMode();

	orbitControl();

	const t = millis() / 1000;
	rotateY(-t/5);

	push();
	box(S);
	pop();

	push()
	translate(0, S/2, 0)
	sphere(10)
	pop()

	for (const mc of mcubes) {
		mc.update();
		mc.draw();
	}
}
